function supplierInputContractCanMutate(){return window.AZIEL_ADMIN_AUTH?.hasPermission?.("OWNER_ROUTING_MANAGE")===true}
function inputContractFieldRow(field={}){const options=(field.options||[]).map(option=>`${option.label||option.value} -> ${option.value}`).join("\n"),transform=field.transformationId||"DIRECT";return `<fieldset data-input-contract-field><label>Label<input name="label" value="${scEscape(field.label||"")}" required></label><label>Customer field<input name="customerField" value="${scEscape(field.customerField||field.azielField||field.name||"")}" pattern="[a-z][A-Za-z0-9]{0,39}" required></label><label>Type<select name="type"><option value="text">Text</option><option value="numeric-text" ${["number","numeric-text"].includes(field.type)?"selected":""}>Numeric text</option><option value="select" ${field.type==="select"?"selected":""}>Select</option></select></label><label><input name="required" type="checkbox" ${field.required===false?"":"checked"}> Required</label><label>Provider destination<input name="providerField" value="${scEscape(field.providerField||"")}" pattern="[a-z][a-z0-9_]{0,63}" required></label><label>Combine rule<select name="transformationId">${["DIRECT","JOIN_WITH_SPACE","JOIN_WITH_PIPE","JOIN_WITH_COLON","JOIN_WITH_DASH"].map(value=>`<option value="${value}" ${transform===value?"selected":""}>${value.replaceAll("_"," ")}</option>`).join("")}</select></label><label>Select options (Label -> value)<textarea name="options" rows="3">${scEscape(options)}</textarea></label><label>Minimum length<input name="minLength" type="number" min="0" max="512" value="${scEscape(field.constraints?.minLength??"")}"></label><label>Maximum length<input name="maxLength" type="number" min="1" max="512" value="${scEscape(field.constraints?.maxLength??"")}"></label><label>Validation pattern (only if evidenced)<input name="pattern" value="${scEscape(field.constraints?.pattern||"")}"></label></fieldset>`}
async function openSupplierInputContractReview(productId){const modal=document.getElementById("supplierInputContractModal"),body=document.getElementById("supplierInputContractBody");if(!modal||!body)return;modal.hidden=false;body.innerHTML='<div class="supplier-catalog-loading">Loading customer information…</div>';try{const data=await adminFetch(`/api/admin/supplier-catalog/products/${encodeURIComponent(productId)}/input-contract`),r=data.review;if(!data?.success)throw new Error(data?.message||"Customer information setup unavailable");const current=r.product.normalizedInputContract||{},fields=current.fields?.length?current.fields:[{}],can=supplierInputContractCanMutate();body.innerHTML=`<form class="supplier-reconciliation-form"><div class="supplier-reconciliation-warning"><strong>Use authoritative supplier information.</strong><br>${scEscape(r.warning)}</div>${statusLine("Supplier",r.product.supplierCode,r.product.supplierName)}${statusLine("Product",r.product.displayName,r.product.supplierProductCode)}${statusLine("Protocol",r.product.protocol)}<h4>Customer information</h4><div data-input-contract-fields>${fields.map(inputContractFieldRow).join("")}</div><button class="admin-secondary-btn" type="button" data-add-input-field>+ Add field</button><label><input name="noCustomerInput" type="checkbox" ${current.noCustomerInput?"checked":""}> No customer information required</label><section><h4>Customer Preview</h4><div data-customer-preview>Fields entered above will be shown to the customer.</div><h4>Supplier Request Preview</h4><div data-supplier-preview>Approved destinations and combine rules only; no live request is sent.</div></section><label>Authoritative source reference<input name="evidenceReference" required value="${scEscape(current.review?.evidenceReference||"")}" placeholder="Provider documentation or support reference"></label><label>Evidence excerpt<textarea name="evidenceExcerpt" rows="4" required placeholder="Must contain each exact provider destination">${scEscape(current.review?.evidenceExcerpt||"")}</textarea></label><label><input name="confirmed" type="checkbox" required> I verified this customer information contract against the recorded source.</label><button class="admin-primary-btn" type="submit" ${can?"":"disabled"}>Approve</button>${can?"":"<small>Owner permission is required.</small>"}</form>`;const form=body.querySelector("form");form.querySelector("[data-add-input-field]").addEventListener("click",()=>form.querySelector("[data-input-contract-fields]").insertAdjacentHTML("beforeend",inputContractFieldRow()));form.addEventListener("submit",async event=>{event.preventDefault();if(!can)return;const rows=[...form.querySelectorAll("[data-input-contract-field]")].map(row=>{const constraints={},min=row.querySelector('[name="minLength"]').value,max=row.querySelector('[name="maxLength"]').value,pattern=row.querySelector('[name="pattern"]').value.trim();if(min!=="")constraints.minLength=Number(min);if(max!=="")constraints.maxLength=Number(max);if(pattern)constraints.pattern=pattern;const options=row.querySelector('[name="options"]').value.split("\n").map(line=>{const parts=line.split("->");return{label:(parts[0]||"").trim(),value:(parts[1]||parts[0]||"").trim()}}).filter(option=>option.value);return{label:row.querySelector('[name="label"]').value.trim(),customerField:row.querySelector('[name="customerField"]').value.trim(),providerField:row.querySelector('[name="providerField"]').value.trim(),type:row.querySelector('[name="type"]').value,transformationId:row.querySelector('[name="transformationId"]').value,required:row.querySelector('[name="required"]').checked,options,constraints}}).filter(row=>row.customerField||row.providerField);const result=await adminFetch(`/api/admin/supplier-catalog/products/${encodeURIComponent(productId)}/input-contract/approve`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({sourceLock:r.sourceLock,fields:rows,noCustomerInput:form.elements.noCustomerInput.checked,evidenceReference:form.elements.evidenceReference.value.trim(),evidenceExcerpt:form.elements.evidenceExcerpt.value.trim(),confirmed:form.elements.confirmed.checked})});if(!result?.success)throw new Error(result?.message||"Customer information approval failed");modal.hidden=true;if(supplierCatalogState.selectedOfferId)await openSupplierCatalogOffer(supplierCatalogState.selectedOfferId)})}catch(error){body.innerHTML=`<div class="supplier-catalog-error">${scEscape(error.message)}</div>`}}
document.addEventListener("DOMContentLoaded",()=>{const detail=document.getElementById("supplierCatalogDetail"),modal=document.getElementById("supplierInputContractModal");if(detail){new MutationObserver(()=>{const productId=detail.querySelector("[data-input-contract-review]")?.dataset.productId;if(productId||!supplierCatalogState.selectedOfferId)return;const row=supplierCatalogState.offers?.find?.(item=>item.offerId===supplierCatalogState.selectedOfferId);if(["FAZERCARDS","WONDD"].includes(row?.supplierCode))detail.insertAdjacentHTML("beforeend",`<button class="admin-secondary-btn" type="button" data-input-contract-review data-product-id="${scEscape(row.supplierProductId)}">Configure customer information</button>`)}).observe(detail,{childList:true})}detail?.addEventListener("click",event=>{const button=event.target.closest("[data-input-contract-review]");if(button)openSupplierInputContractReview(button.dataset.productId)});modal?.addEventListener("click",event=>{if(event.target===modal||event.target.closest("[data-input-contract-close]"))modal.hidden=true})});

const productActivationState={products:[],selectedProduct:"",supplierMarket:"",customerMarket:"TH",loaded:false,requestId:0};
async function loadProductActivation({detail=false}={}){const requestId=++productActivationState.requestId,startedAt=performance.now(),products=document.getElementById("activationProducts"),packages=document.getElementById("activationPackages"),search=document.getElementById("activationProductSearch")?.value?.trim()||"";if(products&&!detail)products.innerHTML='<div class="supplier-catalog-loading">Loading prepared canonical products…</div>';if(packages&&detail)packages.innerHTML='<div class="supplier-catalog-loading">Computing current readiness…</div>';try{const params=new URLSearchParams({customerMarket:productActivationState.customerMarket});if(search&&!detail)params.set("search",search);if(detail&&productActivationState.selectedProduct)params.set("productCode",productActivationState.selectedProduct);if(detail&&productActivationState.supplierMarket)params.set("supplierMarket",productActivationState.supplierMarket);const data=await adminFetch("/api/admin/product-activation?"+params);if(requestId!==productActivationState.requestId)return;if(!data?.success)throw new Error(data?.message||"Product Activation unavailable");if(!detail){productActivationState.products=data.products||[];productActivationState.loaded=true;renderActivationProducts()}else{renderActivationMarkets(data.markets||[]);renderActivationPackages({...data,requestDurationMs:Math.round(performance.now()-startedAt)})}}catch(error){if(requestId!==productActivationState.requestId)return;const target=detail?packages:products;if(target)target.innerHTML='<div class="supplier-catalog-error">'+scEscape(error.message)+'</div>'}}
function renderActivationProducts(){const el=document.getElementById("activationProducts");if(!el)return;el.innerHTML=productActivationState.products.map(product=>`<button type="button" class="activation-product ${product.productCode===productActivationState.selectedProduct?"active":""}" data-activation-product="${scEscape(product.productCode)}"><strong>${scEscape(product.name)}</strong><code>${scEscape(product.productCode)}</code><span>${product.packageCount} packages · ${scEscape(product.suppliers.join(", "))}</span><small>${scEscape(product.supplierMarkets.join(", "))} · ${scEscape(product.commerceState)} · ${product.publishedPackageCount} published</small></button>`).join("")||'<div class="supplier-catalog-empty">No mapped canonical products match.</div>'}
function renderActivationMarkets(markets){const select=document.getElementById("activationSupplierMarket");if(!select)return;if(!productActivationState.supplierMarket||!markets.includes(productActivationState.supplierMarket))productActivationState.supplierMarket=markets[0]||"";select.innerHTML=markets.map(market=>`<option ${market===productActivationState.supplierMarket?"selected":""}>${scEscape(market)}</option>`).join("")||'<option value="">No mapped markets</option>'}
function activationLine(label,value,note=""){return `<div class="activation-line"><span>${scEscape(label)}</span><b>${scEscape(value==null?"":value)}</b>${note?`<small>${scEscape(note)}</small>`:""}</div>`}
function humanActivationBlocker(code=""){const messages={CURRENT_SUPPLIER_COST_MISSING:"Supplier cost needs review.",FULFILLMENT_ELIGIBILITY_UNKNOWN:"Supplier eligibility has not been reviewed yet.",FULFILLMENT_NOT_READY:"Fulfillment setup is not ready.",FULFILLMENT_PROCESSOR_NOT_READY:"The fulfillment processor is not ready.",INPUT_NOT_READY:"Customer input fields need configuration.",MAPPING_DISABLED:"The supplier route is currently off.",MAPPING_EXECUTION_NOT_API:"The route is not configured for API execution.",MAPPING_NOT_PRIMARY:"Select a primary production supplier.",PRICING_NOT_READY:"A customer price needs review.",PROVIDER_FEATURE_GATE_OFF:"Supplier API fulfillment is currently off.",SUPPLIER_ADAPTER_NOT_READY:"The supplier connection is not ready.",CUSTOMER_MARKET_PRICE_NOT_PUBLISHED:"Publish a customer price before selling."};return messages[code]||String(code).toLowerCase().replaceAll("_"," ").replace(/^./,value=>value.toUpperCase())+"."}
function productNextAction(row){const action=row.readiness?.actions?.[0]?.label;if(action)return action;const blocker=row.readiness?.blockers?.[0];return blocker?humanActivationBlocker(blocker):row.publication?.published?"No action needed":"Publish when ready"}
function renderActivationPackages(data){const el=document.getElementById("activationPackages");if(!el)return;const grouped=new Map();(data.packages||[]).forEach(row=>{if(!grouped.has(row.packageCode))grouped.set(row.packageCode,[]);grouped.get(row.packageCode).push(row)});el.innerHTML=`<header class="activation-summary"><div><span class="admin-status-pill">${data.commerceMarketSupported?"Commerce market supported":"Preparation only"}</span><h3>${scEscape(productActivationState.selectedProduct)} · ${scEscape(productActivationState.supplierMarket)} → ${scEscape(data.customerMarket)}</h3></div><p>Selection never publishes. Price publication remains in Daily Pricing; package publication remains an explicit guarded command.</p></header>${[...grouped.values()].map(routes=>{const first=routes[0],published=first.publication.published;return `<article class="activation-package"><header><div><strong>${scEscape(first.packageName)}</strong><code>${scEscape(first.packageCode)}</code></div><span class="admin-status-pill">${first.readiness.ready?"READY":"BLOCKED"}</span></header><div class="activation-route-list">${routes.map(row=>`<div class="activation-route" data-activation-mapping="${scEscape(row.mappingId)}">${activationLine("Supplier",row.supplierCode,`${row.supplierMarket} · ${row.supplierProductCode}/${row.supplierPackageCode}`)}${activationLine("Offer",row.supplierOfferName,row.availability.state+" · "+row.availability.evidenceCode)}${activationLine("Cost",row.supplierCost==null?"MISSING":`${row.supplierCost} ${row.supplierCurrency}`,row.supplierCostCapturedAt||"")}${activationLine("Daily Pricing",row.dailyPricing.previewEligible?"ELIGIBLE":"BLOCKED",row.publishedPrice?`Published ${row.publishedPrice.amount} ${row.publishedPrice.currency}`:"No published price")}${activationLine("Inputs",row.readinessFlags.inputReady?"READY":"INPUT_NOT_READY",(row.requiredFields||[]).join(", "))}${activationLine("Eligibility",row.fulfillmentEligibility.mode,(row.fulfillmentEligibility.allowedCustomerMarkets||[]).join(", "))}${activationLine("Route",row.productionRole,`Mapping ${row.mappingEnabled?"enabled":"disabled"} · ${row.executionMode}`)}${activationLine("Readiness",row.readiness.ready?"READY":row.readiness.blockers.join(", "))}${activationLine("Next actions",(row.readiness.actions||[]).map(item=>item.label).join(" · "))}<div class="activation-actions"><button class="admin-secondary-btn" type="button" data-activation-cost="${scEscape(row.supplierCatalogOfferId)}">Review cost</button><button class="admin-secondary-btn" type="button" data-activation-pricing>Open Daily Pricing</button><button class="admin-secondary-btn" type="button" data-activation-fulfillment>Open Fulfillment</button><select data-activation-role><option ${row.productionRole==="DISABLED"?"selected":""}>DISABLED</option><option ${row.productionRole==="BACKUP"?"selected":""}>BACKUP</option><option ${row.productionRole==="PRIMARY"?"selected":""}>PRIMARY</option></select><button class="admin-secondary-btn" type="button" data-save-route>Save route</button><button class="admin-primary-btn" type="button" data-activation-publish="${published?"false":"true"}" ${(!published&&!row.readiness.ready)?"disabled":""}>${published?"OFF / Unpublish":"Publish / ON"}</button></div></div>`).join("")}</div></article>`}).join("")||'<div class="supplier-catalog-empty">No exact mappings exist for this Product + supplier market.</div>'}`}
