openSupplierReconciliationReview=async function(offerId,trigger=null){
    const modal=document.getElementById("supplierReconciliationModal"),body=document.getElementById("supplierReconciliationBody");if(!modal||!body)return;
    supplierReconciliationReturnFocus=trigger||document.activeElement;modal.hidden=false;body.innerHTML='<div class="supplier-catalog-loading">Loading trusted reconciliation context…</div>';modal.querySelector("[data-reconciliation-close]")?.focus();
    try{
        const data=await adminFetch(`/api/admin/supplier-catalog/offers/${encodeURIComponent(offerId)}/reconciliation`),r=data.reconciliation;if(!data.success)throw new Error(data.message||"Review unavailable");
        const s=r.source,can=supplierReconciliationCanMutate()&&r.productionMutationEnabled===true,candidates=r.candidates||[];
        body.innerHTML=`<form class="supplier-reconciliation-form"><div class="supplier-reconciliation-warning"><strong>${scEscape(r.currentProductionRecommendation)}</strong><br>Names and amounts are evidence only. No candidate is selected automatically.</div>${statusLine("Supplier",s.identity.supplierCode,`${s.productName} · ${s.supplierMarket}`)}${statusLine("Provider identity",`${s.identity.catalogNamespace}/${s.identity.supplierProductCode}/${s.identity.supplierOfferCode}`)}${statusLine("Availability",s.availability.state)}<label>Decision<select name="decisionType"><option value="DEFER_REVIEW">Defer / Needs Review</option><option value="LINK_TO_EXISTING_CANONICAL_PACKAGE">Link to existing package</option><option value="CREATE_CANONICAL_PACKAGE_AND_LINK">Create as new package</option><option value="MARK_SPECIAL_VARIANT_REVIEWED">Mark special variant reviewed</option><option value="MARK_INTENTIONALLY_UNSUPPORTED">Mark intentionally unsupported</option></select></label><label data-existing-target hidden>Canonical package<select name="canonicalPackageId"><option value="">Select an exact canonical package…</option>${candidates.map(c=>`<option value="${scEscape(c.canonicalPackageId)}">${scEscape(c.productCode)} / ${scEscape(c.packageCode)} — ${scEscape(c.displayName)} (${c.existingSupplierMappings.length} mappings)</option>`).join("")}</select></label><div data-create-target hidden><label>Canonical product code<input name="canonicalProductCode" autocomplete="off"></label><label>New package display name<input name="canonicalPackageName" value="${scEscape(s.offerName||"")}" autocomplete="off"></label><small>The package code is deterministic and collision-safe. The new package starts disabled, unpriced, unpublished, and unselected.</small></div><label>Reason code<input name="reasonCode" required value="ADMIN_REVIEWED"></label><label>Review notes<textarea name="reviewNotes" rows="3"></textarea></label><label>Supplier account market<select name="region"><option value="TH">TH</option><option value="MM">MM</option><option value="GLOBAL">GLOBAL</option><option value="ASIA">ASIA</option></select></label><label><input name="confirmed" type="checkbox" required> I reviewed the native identity and entitlement evidence.</label><button class="admin-primary-btn" type="submit" ${can?"":"disabled"}>Confirm reviewed decision</button>${can?"":"<small>Production reconciliation mutations are disabled.</small>"}</form>`;
        const form=body.querySelector("form"),decision=form.elements.decisionType,existing=form.querySelector("[data-existing-target]"),create=form.querySelector("[data-create-target]");
        const sync=()=>{existing.hidden=decision.value!=="LINK_TO_EXISTING_CANONICAL_PACKAGE";create.hidden=decision.value!=="CREATE_CANONICAL_PACKAGE_AND_LINK"};decision.addEventListener("change",sync);sync();
        form.addEventListener("submit",async event=>{event.preventDefault();if(!can)return;try{const payload={decisionType:decision.value,confirmed:form.elements.confirmed.checked,canonicalPackageId:form.elements.canonicalPackageId.value||undefined,canonicalProductCode:form.elements.canonicalProductCode.value.trim()||undefined,canonicalPackageName:form.elements.canonicalPackageName.value.trim()||undefined,region:form.elements.region.value,reasonCode:form.elements.reasonCode.value.trim(),reviewNotes:form.elements.reviewNotes.value.trim(),expectedSource:s.identity,decisionVersion:r.nextDecisionVersion,requestIdempotencyKey:supplierReconciliationIdempotency()};const result=await adminFetch(`/api/admin/supplier-catalog/offers/${encodeURIComponent(offerId)}/reconciliation`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!result.success)throw new Error(result.message||"Decision failed");closeSupplierReconciliationReview();document.dispatchEvent(new CustomEvent("aziel:reconciliation-complete",{detail:{offerId}}));await openSupplierCatalogOffer(offerId)}catch(error){body.insertAdjacentHTML("afterbegin",`<div class="supplier-catalog-error">${scEscape(error.message||"Review failed. Review the latest supplier evidence and try again.")}</div>`)} });
    }catch(error){body.innerHTML=`<div class="supplier-catalog-error">${scEscape(error.message)}</div>`}
};
document.addEventListener("click",event=>{const modal=document.getElementById("supplierReconciliationModal");if(!modal||modal.hidden)return;if(event.target===modal||event.target.closest("[data-reconciliation-close]")){event.preventDefault();event.stopImmediatePropagation();closeSupplierReconciliationReview()}},true);
document.addEventListener("keydown",event=>{const modal=document.getElementById("supplierReconciliationModal");if(!modal||modal.hidden)return;if(event.key==="Escape"){event.preventDefault();event.stopImmediatePropagation();closeSupplierReconciliationReview();return}if(event.key==="Tab"){const focusable=[...modal.querySelectorAll('button:not([disabled]),select:not([disabled]),input:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(element=>element.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}},true);
